def langford(n):
    seq = [0] * (2 * n)
    def place(v):
        if v == 0:
            return True
        for i in range(2 * n - v - 1):
            if seq[i] == 0 and seq[i + v + 1] == 0:
                seq[i] = v
                seq[i + v + 1] = v
                if place(v - 1):
                    return True
                seq[i] = 0
                seq[i + v + 1] = 0
        return False
    if place(n):
        return seq
    else:
        return "UNSATISFIABLE"
result = langford(35)
